            return result
        return wrapper
    return decorator


def counted(metric_name: str) -> Callable[[Callable[..., _T]], Callable[..., _T]]:
    """Decorator that increments a counter each time the function is called."""
    def decorator(fn: Callable[..., _T]) -> Callable[..., _T]:
